 for(const station of ['kitchen','supply','alchemy'] as const){
  await clickV(win,'station-'+station);const manual=await control(win,'manual');assert.equal(manual.hidden,station!=='kitchen','manual navigation should respect canNavigate for '+station);check('finite plan station route and manual navigation gate '+station,{manualHidden:manual.hidden});
  if(station==='kitchen'){
   await clickV(win,'item-soup');const itemRef=JSON.stringify(vsel('plan-item-art')),submitRef=JSON.stringify(vsel('plan-submit-art'));
   const art=await js<any>(win,'(()=>{const a=document.querySelector('+itemRef+'),b=document.querySelector('+submitRef+');return{selected:a.dataset.art,kind:a.dataset.kind,submit:b.dataset.art,submitKind:b.dataset.kind}})()');
   assert.equal(art.selected,'soup');assert.equal(art.submit,'soup','plan-submit picture tracks selected product');assert.equal(art.submitKind,'food');
   const before=structuredClone(profile()),planAction={type:'village-plan',station:'kitchen',item:'soup',count:10,reserve:0,sell:false} as GameAction,started=await actionV(win,'plan-start',planAction);
   assert.equal(started.village?.plans.kitchen?.item,'soup');assert.equal(started.village?.plans.kitchen?.remaining,10);const planId=started.village!.plans.kitchen!.id;
   const stopAction={type:'village-plan-stop',station:'kitchen',id:planId} as GameAction,stopped=await actionV(win,'plan-stop',stopAction);
   assert.equal(stopped.village?.plans.kitchen,null);assert.equal(amount(stopped,'mushroom'),amount(before,'mushroom'));assert.equal(amount(stopped,'gel'),amount(before,'gel'));
   check('finite kitchen plan starts one batch and cancellation refunds the active recipe',{planId,item:'soup',startedRemaining:10,mushroom:amount(stopped,'mushroom'),gel:amount(stopped,'gel')});
  }
 }
 await clickNative(win,'cCampBack');await until(()=>js<boolean>(win,'!document.getElementById("cCampHome").hidden&&document.getElementById("cCampWorkspace").hidden'),'camp back closes village workspace');
 await goVillage(win,'csLodge','projects');await selectProject(win,'teahouse');await clickV(win,'project-back');const detailSelector=JSON.stringify(vsel('project-detail'));await until(()=>js<boolean>(win,'document.querySelector('+detailSelector+').hidden'),'project-back returns to overview');await backScene(win);
 const ids=await js<string[]>(win,'[...document.querySelectorAll("#villageUi [data-v-ref]")].map(e=>e.dataset.vRef)');assert.ok(ids.length>50);await ensureStableRefs(win);await goVillage(win,'csVisitor2','regulars',{regular:'merchant'});await newNav(win,'regulars');await clickV(win,'regular-merchant');await assertStableRefs(win,'regular selection and navigation');await backScene(win);
 const before=profile().sequence;await clickNative(win,'cClose');await until(()=>!shell?.arenaWindow,'inner casual close through native bridge');check('close control destroys hidden casual arena without activation',{sequence:before,windows:snapshots()});
 win=await openCasual();await clickNative(win,'csMap');await until(()=>js<boolean>(win,'!document.getElementById("cPanel-adventure").hidden'),'legacy page opens before workspace shortcut check');await clickNative(win,'cVillageShortcut');const overviewSelector=JSON.stringify(vsel('panel-projects'));await until(()=>js<boolean>(win,'!document.getElementById("cPanel-village").hidden&&!document.querySelector('+overviewSelector+').hidden'),'old-page cVillageShortcut enters new project overview');await clickNative(win,'cCampBack');await clickNative(win,'cClose');await until(()=>!shell?.arenaWindow,'second hidden casual close');
 check('scene, project-detail, workspace-return, close/reopen and old-page shortcut routes remain reachable',{refs:ids.length,shortcut:'cVillageShortcut',profileSequence:profile().sequence});
